<?php
require "conexao.php"; require "funcoes.php"; $erro=""; $nome=""; $salario="";
if($_SERVER["REQUEST_METHOD"]==="POST"){verificarToken();$nome=trim($_POST["nome_patente"]??"");$salario=str_replace(',','.',trim($_POST["salario"]??""));if($nome===""||mb_strlen($nome)>80)$erro="Informe o nome da patente (até 80 caracteres).";elseif(!is_numeric($salario)||$salario<0||$salario>99999999)$erro="Informe um salário válido.";else{try{$stmt=$pdo->prepare("INSERT INTO patentes(nome_patente,salario) VALUES(:nome,:salario)");$stmt->execute([":nome"=>$nome,":salario"=>$salario]);header("Location: listar_patentes.php?sucesso=".urlencode("Patente cadastrada!"));exit;}catch(PDOException $e){$erro="Essa patente já existe ou não pôde ser cadastrada.";}}}
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cadastrar patente</title><link rel="stylesheet" href="estilo.css"></head><body><main class="container formulario"><h1>Cadastrar patente</h1><?php if($erro): ?><p class="erro"><?= escapar($erro) ?></p><?php endif; ?><form method="post"><input type="hidden" name="token" value="<?= escapar($_SESSION["token"]) ?>"><label>Nome da patente<input name="nome_patente" maxlength="80" value="<?= escapar($nome) ?>" required></label><label>Salário (R$)<input name="salario" type="number" min="0" step="0.01" value="<?= escapar($salario) ?>" required></label><button type="submit">Cadastrar patente</button></form><p><a href="listar_patentes.php">Voltar</a></p></main></body></html>
